def dumps(x):return json.dumps(x,ensure_ascii=False,sort_keys=True,default=str)
class NextResolver(BlockedResolver):
 def profile(self,row):
  p=PROFILES[row['book'],row['bloque'],row['serie_id']];require(row['titulo']==row['metrica_literal']==p['title'],'Next universal metric changed');s=self.sources[row['book']]
  require(all(s.text(row['bloque'],a)==t for a,t in p['headers']),'Next source caption changed');return p
 def binding(self,row):
  p=self.profile(row);source=self.sources[row['book']];sheet=row['bloque'];part='xl/charts/'+p['sid'].split('_')[0]+'.xml';require(row['parte_grafico_imagen']==part,'Next chart identity changed')
  if p.get('mode')=='direct':
   b=SourceResolver.binding(self,row);require(b['name_ref']==p['name_ref'] and b['value_ref']==p['val'] and b['category_ref']==p['cat'] and b['label']==p['label'],'Next direct source binding changed')
   require(b['axis_id']==p['axis_id'] and b['axis_format']==p['fmt'] and b['divisor']==p['divisor'] and b['multiplier']==p['multiplier'] and b['display_unit']=='none','Next direct associated axis changed');return b
  root=ET.fromstring(source.xml.parts[part]);node=root.findall('.//c:ser',C)[int(p['sid'].split('_s')[1])-1];vr=node.find('c:val/c:numRef/c:f',C);require(vr is not None and vr.text==p['val'],'Next grid values changed');vs,vc=ref_cells(vr.text)
  if p.get('mode')=='missing_name':
   literal=node.find('c:tx/c:v',C);require(node.find('c:tx',C) is None and source.text(sheet,p['name_cell'])==p['label'],'Historical physical name changed');cat=node.find('c:cat/c:numRef/c:f',C);require(cat is not None and cat.text==p['cat'],'Historical category reference changed');cr=p['cat'];cs,cc=ref_cells(cr);name_ref=f"'{sheet}'!{p['name_cell']}";name_basis='explicit_value_row_header_recovery'
  else:
   name=node.find('c:tx/c:strRef/c:f',C);require(name is not None and name.text==p['name_ref'],'Next grid name reference changed');ns,nc=ref_cells(name.text);require(ns==vs==sheet and len(nc)==1 and source.text(ns,nc[0])==p['label'],'Next grid physical name changed');require(points(node.find('c:tx/c:strRef/c:strCache',C))=={0:p['label']},'Next grid name cache changed');require(node.find('c:cat',C) is None,'Next omitted category origin changed')
   col=re.match('[A-Z]+',nc[0])[0];header=int(re.search('[0-9]+',nc[0])[0]);rr=[int(re.search('[0-9]+',a)[0]) for a in vc];require(all(re.match('[A-Z]+',a)[0]==col for a in vc) and rr==list(range(header+1,header+1+len(vc))),'Next grid header/value alignment changed');cc=[p['category_column']+str(i) for i in rr];cs=sheet;cr=f"'{sheet}'!${p['category_column']}${rr[0]}:${p['category_column']}${rr[-1]}";name_ref=name.text;name_basis='source_scalar'
   peers=[n.text for n in root.findall('.//c:ser/c:cat/c:numRef/c:f',C)+root.findall('.//c:ser/c:cat/c:strRef/c:f',C)];require(cr in peers,'Next grid lacks matching explicit peer category reference')
  require(vs==cs==sheet and len(vc)==len(cc),'Next grid source shape changed');categories=[self.category(source,cs,a) for a in cc];require(all(isinstance(v,str) and v.strip() for v in categories),'Next physical categories missing')
  values={i:source.number(vs,a) for i,a in enumerate(vc)};values={i:v for i,v in values.items() if v is not None};cache=points(node.find('c:val/c:numRef/c:numCache',C));require(set(cache)==set(values) and all(Decimal(cache[i])==v for i,v in values.items()),'Next source/cache vector mismatch')
  parent=next(x for x in root.iter() if node in list(x));ids={x.get('val') for x in parent.findall('c:axId',C)};axes=[x for x in root.findall('.//c:valAx',C) if x.find('c:axId',C).get('val') in ids];require(len(axes)==1,'Next associated axis ambiguous');axis=axes[0];fmt=axis.find('c:numFmt',C);require(axis.find('c:axId',C).get('val')==p['axis_id'] and fmt is not None and fmt.get('formatCode')==p['fmt'],'Next associated axis changed');display=axis.find('c:dispUnits',C)
  if p['divisor']==1000:require(display is not None and display.find('c:builtInUnit',C).get('val')=='thousands','Next thousand-person display changed')
  else:require(display is None,'Next unexpected display scaling')
  d,m=format_effect(p['fmt']);require(d==1 and m==p['multiplier'],'Next format scale changed')
  return dict(label=p['label'],name_ref=name_ref,category_ref=cr,value_ref=vr.text,value_sheet=sheet,cells=vc,categories=categories,valid_indices=set(values),axis_id=p['axis_id'],axis_format=p['fmt'],display_unit='thousands' if p['divisor']==1000 else 'none',divisor=Decimal(p['divisor']),multiplier=Decimal(p['multiplier']),mode='reviewed_physical_source_grid',category_basis='source_cells' if p.get('mode')=='missing_name' else 'reviewed_source_grid',name_basis=name_basis)
 def title_proof(self,row,texts):return self.profile(row)['headers']
 def labour_checksum(self):
  s=self.sources['2025'];evidence=[]
  for rr in range(5,18):
   cells=[col+str(rr) for col in 'CDEFG'];values=[s.number('Gráfico 17',cell) for cell in cells]
   if rr==15:require(all(v is None for v in values),'Labour intentionally empty source row changed');continue
   require(all(v is not None for v in values),'Labour contribution vector incomplete');residual=sum(values[1:],Decimal(0))-values[0];require(abs(residual)<=Decimal('1e-14'),'Labour decomposition conflict');evidence.append(dict(cells=cells,values=list(map(str,values)),residual=str(residual)))
  return dict(total='C',components='D:G',tolerance='1e-14',blank_row=15,rows=evidence,total_not_additional_component=True)
 def unit_spec(self,row,texts,binding):
  p=self.profile(row);require(binding['divisor']==p['divisor'] and binding['multiplier']==p['multiplier'],'Next unit scaling changed');proof=dict(headers=p['headers'],unit=p['unit'],role=p['role'],axis_id=binding['axis_id'],axis_format=binding['axis_format'],divisor=p['divisor'],multiplier=p['multiplier'])
  if p['pdf']:proof['pdf']=self.pdf(row['book'],*p['pdf'])
  if p.get('external'):proof['technical_pdf']=self.external(row['bloque'])
  if row['bloque']=='Gráfico 17':proof['decomposition']=self.labour_checksum();proof['population_age_context']='15-74';proof['pdf_population']=self.pdf('2025',52,['detrae -0,4 puntos porcentuales del crecimiento real potencial'])
  self.supplements[row['book'],row['bloque']]=proof;return 'unidad del contrato fuente acreditado',p['unit'],'next_bounded_source_contract',('next_source_contract',dumps(proof))
 def review_next(self,row):
  try:
   p=self.profile(row);require(row['serie_literal']==(None if p.get('mode')=='missing_name' else p['label']),'Next universal series changed');b=self.binding(row);match=re.fullmatch(re.escape(row['serie_id'])+r'_p([0-9]+)',row['id'] or '');require(match is not None,'Next point identity changed');index=int(match[1]);require(index in b['valid_indices'],'Next point outside verified source vector');category=b['categories'][index];original=row['periodo_categoria_literal']
   if b['category_basis']=='reviewed_source_grid':require(original is None,'Next omitted universal category changed')
   elif original!=category:require(row['bloque']=='Gráfico 17' and isinstance(category,str) and '\n' in category and category.replace('\n',' / ')==original,'Next lossless category representation changed')
   shadow=dict(row,serie_literal=b['label'],periodo_categoria_literal=category);status,result=SourceResolver.review(self,shadow)
   if result is None:return status,None
   proof=dict(self.supplements[row['book'],row['bloque']],universal_metric=row['metrica_literal'],universal_title=row['titulo'],universal_series=row['serie_literal'],universal_category=original,source_category=category,category_ref=b['category_ref'],name_ref=b['name_ref'],value_ref=b['value_ref'],category_semantics=p.get('category_semantics','source_category_as_labelled'),category_origin=b['category_basis'])
   if p.get('resolved_metric'):result=result[:4]+(p['resolved_metric'],)+result[5:];proof['resolved_metric']=p['resolved_metric']
   return 'usable_next',result+(original,dumps(proof),row['serie_literal'],row['hoja_valor'],row['celda_valor'],'{}',p['role'],p.get('category_semantics','source_category_as_labelled'),dumps(proof))
  except (ValueError,ArithmeticError,KeyError,IndexError,AttributeError,TypeError,StopIteration) as e:return 'next_evidence_review:'+str(e),None

def collect(c):
 require(sha(PREVIOUS)==PREVIOUS_SHA,'Previous database changed');require(c.execute('SELECT count(*) FROM blocked_usable_keys').fetchone()[0]==39879,'Previous admissions changed');q=c.execute('SELECT * FROM blocked_numeric_queue ORDER BY book,row_number');names=[n[0] for n in q.description];data=[dict(zip(names,v)) for v in q.fetchall()];require(len(data)==7334,'Previous queue changed');r=NextResolver();rows=[];reviews=[];deferrals=[]
 try:
  for row in data:
   key=row['book'],row['bloque'],row['serie_id']
   if key in PROFILES:
    status,result=r.review_next(row);reviews.append((row['book'],row['row_number'],status))
    if result is not None:rows.append(result)
   elif row['book']=='2026' and row['bloque']=='Anexo I. Gr 7A' and row['serie_literal'] is not None:deferrals.append((row['book'],row['row_number'],'population_identity_contract_pending',dumps(dict(source_header_B19='Madres de nacionalidad española',pdf_page=85,reason='caption_and_population_header_not_reconciled',universal_series=row['serie_literal']))))
   elif row['book']=='2025' and row['bloque']=='Gráfico 78' and row['serie_id'] in ['chart132_s1','chart132_s2','chart133_s1','chart133_s2']:deferrals.append((row['book'],row['row_number'],'monetary_MM_euro_unit_contract_pending',dumps(dict(display_unit='thousands',divisor=1000,caption_literal='MM€ Y % PIB',action='do_not_infer_currency_conversion'))))
  pages=[(b,p,PDF_HASHES[b],t) for (b,p),t in sorted(r.pdf_pages.items())];external=[(str(CLIMATE_PDF.relative_to(ROOT)),CLIMATE_URL,CLIMATE_SHA,page,text) for page,text in sorted(r.external_pages.items())]
 finally:r.close()
 return rows,reviews,pages,external,deferrals

def expressions():return [('next_usable_keys','SELECT * FROM blocked_usable_keys UNION ALL SELECT book,row_number FROM next_observations'),('next_numeric_queue',"SELECT s.*,CASE WHEN r.status='literal_series_source_conflict' THEN r.status ELSE s.blocked_reason END next_reason FROM blocked_numeric_queue s LEFT JOIN next_review r USING(book,row_number) WHERE COALESCE(r.status,'')<>'usable_next'")]
def build(output):
 output=Path(output).resolve();require(output.is_relative_to(ROOT) and not output.exists(),'Output must be new project directory');require(sha(PREVIOUS)==PREVIOUS_SHA,'Previous database changed');output.mkdir(parents=True);db=output/'next_groups.duckdb';shutil.copyfile(PREVIOUS,db)
 with duckdb.connect(str(db)) as c:
  rows,reviews,pages,external,deferrals=collect(c);c.execute('CREATE TABLE next_observations AS SELECT * FROM blocked_observations WHERE false');c.execute('ALTER TABLE next_observations ADD PRIMARY KEY(book,row_number)')
  if rows:c.executemany('INSERT INTO next_observations VALUES ('+','.join('?' for _ in FIELDS)+')',rows)
  c.execute('CREATE TABLE next_review(book VARCHAR,row_number INTEGER,status VARCHAR,PRIMARY KEY(book,row_number))');c.executemany('INSERT INTO next_review VALUES (?,?,?)',reviews)
  c.execute('CREATE TABLE next_pdf_evidence(book VARCHAR,page INTEGER,pdf_sha256 VARCHAR,text VARCHAR,PRIMARY KEY(book,page))')
  if pages:c.executemany('INSERT INTO next_pdf_evidence VALUES (?,?,?,?)',pages)
  c.execute('CREATE TABLE next_external_evidence(path VARCHAR,url VARCHAR,sha256 VARCHAR,page INTEGER,text VARCHAR,PRIMARY KEY(path,page))')
  if external:c.executemany('INSERT INTO next_external_evidence VALUES (?,?,?,?,?)',external)
  c.execute('CREATE TABLE next_deferrals(book VARCHAR,row_number INTEGER,reason VARCHAR,evidence VARCHAR,PRIMARY KEY(book,row_number))')
  if deferrals:c.executemany('INSERT INTO next_deferrals VALUES (?,?,?,?)',deferrals)
  for name,sql in expressions():c.execute('CREATE VIEW '+name+' AS '+sql)
  sources=c.execute('SELECT * FROM sources ORDER BY book').fetchall()
 report=dict(status='built_pending_validation',added=len(rows),admitted=39879+len(rows),numeric_pending=7334-len(rows),previous_sha256=PREVIOUS_SHA,code_sha256=sha(Path(__file__)),db_sha256=sha(db),sources=sources,external_source_sha256=CLIMATE_SHA,rag_integrated=False)
 (output/'manifest.json').write_text(dumps(report),encoding='utf-8');return report

def check_new(c):
 rows,reviews,pages,external,deferrals=collect(c)
 for table,expected in [('next_observations',rows),('next_review',reviews),('next_pdf_evidence',pages),('next_external_evidence',external),('next_deferrals',deferrals)]:
  actual=c.execute('SELECT * FROM '+table).fetchall();require(len(actual)==len(expected) and set(actual)==set(expected),'Next evidence mismatch: '+table)
 for name,sql in expressions():
  require(c.execute('SELECT * FROM '+name+' LIMIT 0').description==c.execute(sql+' LIMIT 0').description,'Next view columns changed')
  for a,b in [(name,'('+sql+')'),('('+sql+')',name)]:require(not c.execute('SELECT * FROM '+a+' EXCEPT ALL SELECT * FROM '+b).fetchall(),'Next view multiplicity changed')
 require(c.execute('SELECT count(*) FROM next_usable_keys').fetchone()[0]==39879+len(rows) and c.execute('SELECT count(*) FROM next_numeric_queue').fetchone()[0]==7334-len(rows),'Next counts changed');require(not c.execute('SELECT book,row_number FROM next_usable_keys INTERSECT SELECT book,row_number FROM next_numeric_queue').fetchall(),'Next partition overlap');require(c.execute('SELECT count(*) FROM (SELECT book,row_number FROM next_usable_keys UNION SELECT book,row_number FROM next_numeric_queue)').fetchone()[0]==47213,'Next candidate partition changed');require(c.execute('SELECT count(*) FROM (SELECT book,row_number FROM next_usable_keys GROUP BY ALL HAVING count(*)<>1)').fetchone()[0]==0,'Next admission collision');require(not c.execute('SELECT book,row_number FROM ready_quarantine INTERSECT SELECT book,row_number FROM next_usable_keys').fetchall(),'Quarantine admitted');return rows

def validate(db):
 previous=validate_previous(db)
 with duckdb.connect(str(db),read_only=True) as c:rows=check_new(c);stats=c.execute('SELECT book,block,unit,quantity_role,count(*) FROM next_observations GROUP BY ALL ORDER BY book,block').fetchall();review=c.execute("SELECT status,count(*) FROM next_review WHERE status<>'usable_next' GROUP BY ALL").fetchall()
 return dict(status='pass',previous_validation=previous['status'],added=len(rows),admitted=39879+len(rows),numeric_pending=7334-len(rows),stats=stats,review=review,previous_sha256=PREVIOUS_SHA,db_sha256=sha(Path(db)),code_sha256=sha(Path(__file__)),external_source_sha256=CLIMATE_SHA,rag_integrated=False)

def query(db,*,book,block,series_id,point_index):
 require(book in ['2025','2026'] and all(isinstance(x,str) and x.strip() for x in [block,series_id]) and type(point_index) is int and point_index>=0,'Exact next identity required')
 with duckdb.connect(str(db),read_only=True) as c:q=c.execute('SELECT t.*,s.xlsx_path,s.xlsx_sha256,s.pdf_path,s.pdf_sha256 FROM next_observations t JOIN next_usable_keys k USING(book,row_number) JOIN sources s USING(book) WHERE book=? AND block=? AND series_id=? AND point_index=?',[book,block,series_id,point_index]);names=[n[0] for n in q.description];rows=q.fetchall()
 if len(rows)!=1:raise LookupError('No unique next point; no fallback')
 return {n:str(v) if isinstance(v,Decimal) else v for n,v in zip(names,rows[0])}

def main():
 p=argparse.ArgumentParser(description=__doc__);s=p.add_subparsers(dest='command',required=True);b=s.add_parser('build');b.add_argument('--output-dir',type=Path,required=True);b=s.add_parser('validate');b.add_argument('--db',type=Path,required=True);b.add_argument('--output',type=Path,required=True);a=p.parse_args()
 if a.command=='build':report=build(a.output_dir)
 else:
  require(not a.output.exists(),'Report exists')
  try:report=validate(a.db)
  except Exception as e:report=dict(status='fail',error=str(e))
  a.output.write_text(dumps(report),encoding='utf-8')
